/**
 * @brief 验证物理关闭 PTY 主从端模拟拔线时 3 秒内触发断链信号且无忙轮询
 */
static bool test_fwd_serial_hangup(TestEnv* env) {
    if (env == nullptr) return false;
    for (int i = 0; i < 16; ++i) {
        bool disp = false;
        aisoc_dbus_dispatch_once(&env->cli_conn, 5, &disp);
        if (!disp) break;
    }
    g_link_sig_received.store(false);
    g_captured_sig_connected = true;

    env->mcu_stop.store(true);
    if (env->mcu_thread.joinable()) {
        env->mcu_thread.join();
    }
    if (env->master_fd >= 0) {
        close(env->master_fd);
        env->master_fd = -1;
    }

    const auto t_start = std::chrono::steady_clock::now();
    aisoc_dbus_method_call_t call = {
        AISOC_DBUS_BUS_NAME_FORWARD, AISOC_DBUS_PATH_FORWARD, AISOC_DBUS_IFACE_FORWARD, "TriggerQuery"
    };
    aisoc_dbus_msg_t req;
    aisoc_dbus_msg_init_call(&call, &req);
    aisoc_dbus_msg_append_byte(&req, 1);
    aisoc_dbus_msg_append_uint32(&req, 500);

    aisoc_dbus_call_opts_t opts = { 1000, true };
    aisoc_dbus_msg_t rep;
    const aisoc_dbus_status_t st = aisoc_dbus_call_method(&env->cli_conn, &req, &opts, &rep);
    aisoc_dbus_msg_unref(&req);
    aisoc_dbus_msg_unref(&rep);

    const auto t_end = std::chrono::steady_clock::now();
    const auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(t_end - t_start).count();

    TEST_CHECK(st == AISOC_DBUS_ERR_DISCONNECTED, "TriggerQuery on hangup returns AISOC_DBUS_ERR_DISCONNECTED");
    TEST_CHECK(ms < 250, "TriggerQuery aborts immediately on hangup without busy loop");
    TEST_CHECK(env->fwd_state.serial_ctx.is_open == false, "serial_ctx.is_open is false after hangup");

    for (int i = 0; i < 20; ++i) {
        bool disp = false;
        aisoc_dbus_dispatch_once(&env->cli_conn, 20, &disp);
        if (g_link_sig_received.load()) break;
    }
    TEST_CHECK(g_link_sig_received.load(), "LinkStateChanged signal received on hangup");
    TEST_CHECK(g_captured_sig_connected == false, "LinkStateChanged indicates disconnected (false)");
    TEST_CHECK(g_captured_sig_node == 1, "LinkStateChanged node is 1");
    return true;
}

