import sys
import tarfile

sys.path.insert(0, str(Path(__file__).resolve().parent))
from build import compile_inputs
from build_common import key, locked, records, sha256, verify_prefix, write_json

PRUNED_XML_PREFIXES = (
    'bed_mesh_', 'input_shaper', 'spoolman', 'timelapse_', 'screws_tilt_',
    'history_dashboard', 'macro_', 'calibration_zoffset',
    'wizard_wifi', 'wizard_input_shaper', 'wifi_',
)
PRUNED_XML_EXACT = {
    'components/bed_mesh_canvas_band.xml',
    'components/bed_mesh_current_mesh_card.xml',
    'components/bed_mesh_profiles_card.xml',
    'print_status_configure_picker.xml',
