    'favorite_macro_config_modal.xml',
    'setting_form_macro_field.xml',
    'setting_macro_card.xml',
}


def copy_file(source: Path, destination: Path) -> None:
    """将 source 复制到 destination，按需建父目录并保留权限。"""
    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(source, destination)


def should_include_asset(folder: str, relative: Path) -> bool:
    """按 DEC-SCREEN-05 裁定资源与非必要 UI XML，返回是否打入生产镜像。"""
    if folder == 'ui_xml':
        sub = relative.relative_to('ui_xml').as_posix()
        if sub in PRUNED_XML_EXACT or any(sub.startswith(p) for p in PRUNED_XML_PREFIXES):
            return False
        return True
    if folder == 'assets/fonts':
        return relative.suffix in ('.bin', '.manifest')
    if folder == 'assets/images':
        if relative.suffix.lower() not in ('.png', '.bin', '.svg'):
            return False
        if 'printers' in relative.parts:
            return relative.name in ('generic.png', 'default.png')
        return 'logo-3d' not in relative.name
    return True


def copy_assets(source: Path, bundle: Path) -> list:
    """从 source 向 bundle 复制生产运行期 UI/主题/字体/图片资源，返回裁剪清单。"""
    omitted = []
    for folder in ('ui_xml', 'config/themes', 'assets/config', 'assets/fonts', 'assets/images', 'assets/zoneinfo'):
        for path in (source / folder).rglob('*'):
            if not path.is_file():
                continue
            relative = path.relative_to(source)
            if should_include_asset(folder, relative):
                copy_file(path, bundle / relative)
            else:
                omitted.append(str(relative))
    # 生产镜像不包含 demo.py 与 demo_gcodes 合成 G-code 样本。
    copy_file(source / 'assets/filaments.json', bundle / 'assets/filaments.json')
    return omitted


def merge_settings(settings: dict, overrides: dict) -> None:
    """把 overrides 深度合并到模板 settings，保留未覆盖默认字段。"""
    for item_key, value in overrides.items():
        if isinstance(value, dict):
            merge_settings(settings.setdefault(item_key, {}), value)
        else:
            settings[item_key] = value


def write_config(source: Path, bundle: Path) -> None:
    """合并 live-profile.json 与模板配置生成生产 settings.json 与 c308l-profile.json。"""
    profile_path = source / 'platform/c308l/live-profile.json'
    profile = json.loads(profile_path.read_text())
    settings = json.loads((source / 'config/settings.json.template').read_text())
    merge_settings(settings, profile['settings'])
    dst = bundle / 'config/settings.json'
    dst.parent.mkdir(parents=True, exist_ok=True)
    dst.write_text(json.dumps(settings, indent=2) + '\n')
    copy_file(profile_path, bundle / 'config/c308l-profile.json')


def copy_licenses(source: Path, bundle: Path, prefix: Path) -> None:
    """复制应用和依赖前缀全部开源许可证文本。"""
    for name in ('LICENSE', 'COPYRIGHT'):
        copy_file(source / name, bundle / name)
    shutil.copytree(prefix / 'licenses', bundle / 'licenses')


def inputs(work: Path) -> tuple:
    """校验构建产物与编译输入一致，阻止打包未编译改动。"""
    result = json.loads((work / 'build-result.json').read_text())
    root = Path(result['root'])
    source = root / 'services/helixscreen'
    if compile_inputs(source) != result['compile_inputs']:
        raise RuntimeError('程序编译输入已变化，请先增量编译')
    if key(records(root / 'third_party/helixscreen/vendor')) != result['vendor_source']:
        raise RuntimeError('第三方源码已变化，请先重新核验依赖并编译')
    binary = work / 'output/helix-screen'
    if sha256(binary) != result['binary']['binary_sha256']:
        raise RuntimeError('待打包程序与构建记录不符')
    prefix = Path(result['dependencies_prefix'])
    verify_prefix(prefix, prefix.name)
    return result, (work / 'source' if result['release'] else source), prefix


